//! Renders the pages. A debug build uses Propel's dev renderer, which reads the
//! views from `resources/views` on each request. A release build renders the
//! views compiled by `build.rs`.

use propel_rocket::PropelView;
use serde::Serialize;

/// The compiled views, generated by `build.rs` from `resources/views`.
#[allow(dead_code, unused_imports, clippy::all)]
pub(crate) mod compiled {
    include!(concat!(env!("OUT_DIR"), "/propel_views.rs"));
}

/// The context every page is rendered with. The pages show fixed text, so it
/// has no fields yet. A field added here must be filled by every handler.
#[derive(Debug, Serialize)]
pub struct Page {}

/// Renders the view `name` with `context`.
#[cfg(debug_assertions)]
pub(crate) fn render_page(name: &str, context: &Page) -> PropelView {
    PropelView::render(name, context)
}

/// Renders the view `name` with `context`, from the compiled view. An unknown
/// name is a bug in a route, so it panics.
#[cfg(not(debug_assertions))]
pub(crate) fn render_page(name: &str, context: &Page) -> PropelView {
    let assets = propel_runtime::Assets::new("public");
    let rendered = match name {
        "home" => compiled::home::render(context, &assets),
        "about" => compiled::about::render(context, &assets),
        "docs.index" => compiled::docs::index::render(context, &assets),
        "errors.not_found" => compiled::errors::not_found::render(context, &assets),
        other => panic!("no compiled view named `{other}`"),
    };
    PropelView::from_result(rendered)
}
